mapper.sql:
n.recipient_id = #{recipientId}
  AND (
    n.type = 'workspace.join'
    OR EXISTS (
      SELECT 1 FROM workspace_member wm
      WHERE wm.workspace_id = n.workspace_id
        AND wm.user_id = n.recipient_id
        AND wm.status = 'active'
    )
  )

mapper.select:
SELECT COALESCE((
  SELECT state_version
  FROM notification_recipient_state
  WHERE recipient_id = #{recipientId}
), 0)

mapper.update:
UPDATE notification
SET read_at = CURRENT_TIMESTAMP
WHERE recipient_id = #{recipientId}
  AND id = #{id}
  AND read_at IS NULL

UPDATE notification
SET read_at = NULL
WHERE recipient_id = #{recipientId}
  AND id = #{id}
  AND read_at IS NOT NULL

UPDATE notification
SET dismissed_at = CURRENT_TIMESTAMP
WHERE recipient_id = #{recipientId}
  AND id = #{id}
  AND dismissed_at IS NULL
  AND resolved_at IS NULL

UPDATE notification
SET dismissed_at = NULL, resolved_at = NULL, read_at = NULL, snoozed_until = NULL
WHERE recipient_id = #{recipientId}
  AND id = #{id}
  AND (dismissed_at IS NOT NULL OR resolved_at IS NOT NULL)

UPDATE notification
SET snoozed_until = #{snoozedUntil}
WHERE recipient_id = #{recipientId}
  AND id = #{id}
  AND dismissed_at IS NULL
  AND resolved_at IS NULL

